import { memo, useDeferredValue, useEffect, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Activity, ArrowDownWideNarrow, ArrowLeft, ArrowRight, Bookmark, CalendarDays, Check, ChevronDown, ChevronRight, Clapperboard, Copy, Database, Download, ExternalLink, FileText, Flame, Heart, Image as ImageIcon, Layers3, LayoutGrid, Lightbulb, ListChecks, LoaderCircle, MessageCircle, PanelLeftClose, PanelLeftOpen, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, Smartphone, Sparkles, Target, Upload, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '@/components/ui/table';
import { Checkbox } from '@/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { appPostTypes, contentTypes, topics, type Annotation, type Bootstrap, type CollectionRequest, type Config, type ContentItem, type Run } from '../shared/schema';
import { api, assetUrl, bootstrap, download } from '@/lib/api';
import { cn, number } from '@/lib/utils';

type View = 'overview' | 'library' | 'needs' | 'runs' | 'timeline' | 'apps' | 'settings';
const viewLabels: Record<View,string> = {overview:'研究总览',library:'热点内容库',needs:'需求洞察',apps:'App 调研',runs:'采集记录',timeline:'采集时间轴',settings:'采集设置'};
const emptyItems: ContentItem[] = [];
const platformName = { douyin:'抖音', xiaohongshu:'小红书' };
const statuses = { collecting:'采集中', analyzing:'分析中', complete:'已完成', partial:'部分完成', blocked:'待处理' };
const dateInShanghai = () => new Date().toLocaleDateString('en-CA', { timeZone:'Asia/Shanghai' });
function FilterSelect({label,value,onValueChange,options}: {label:string;value:string;onValueChange:(value:string)=>void;options:{value:string;label:string}[]}) {
  return <Select value={value} items={options} onValueChange={next=>{if(next!==null) onValueChange(next);}}><SelectTrigger aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(option=><SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select>;
}
function Empty({title,children,icon}: {title:string;children?:ReactNode;icon?:ReactNode}) {
  return <div className="empty">{icon ?? <Layers3 size={30}/>}<h3>{title}</h3><p>{children}</p></div>;
}
function Platform({platform}: {platform:ContentItem['platform']}) { return <span className={`platform ${platform}`}><i/>{platformName[platform]}</span>; }
function FrameImage({item,className}: {item:ContentItem;className?:string}) {
  const [failed,setFailed] = useState(false); const frame = item.frames[0];
  useEffect(() => setFailed(false),[item.id]);
  return frame && !failed ? <img className={className} src={assetUrl(frame.path)} alt={frame.caption || item.title} onError={() => setFailed(true)} loading="lazy" decoding="async"/> : <div className={cn('image-placeholder',className)}><Clapperboard size={22}/><span>暂无截帧</span></div>;
}
function PreviewImage({path,caption}: {path:string;caption:string}) {
  const [loaded,setLoaded]=useState(false);const [failed,setFailed]=useState(false);
  return <div className="preview-media" aria-busy={!loaded&&!failed}>{!loaded&&<div className="preview-message" role="status">{failed?<><ImageIcon size={24}/><span>图片暂时无法读取</span></>:<><LoaderCircle className="spin" size={24}/><span>正在加载画面…</span></>}</div>}{!failed&&<img className={loaded?'is-loaded':''} src={assetUrl(path)} alt={caption} decoding="async" onLoad={()=>setLoaded(true)} onError={()=>setFailed(true)}/>}</div>;
}
function Metric({label,metric,icon}: {label:string;metric:ContentItem['metrics']['likes'];icon:ReactNode}) {
  return <div className="metric"><span>{icon}{label}{metric.basis === 'increment' ? ` · ${metric.window ?? '区间'}新增` : ''}</span><strong>{metric.display || number(metric.value)}</strong></div>;
}
function App() {
  const [data,setData] = useState<Bootstrap | null>(null); const [loading,setLoading] = useState(true);
  const [error,setError] = useState(''); const [notice,setNotice] = useState(''); const [view,setView] = useState<View>('overview');
  const [sidebarCollapsed,setSidebarCollapsed] = useState(false);
  const [visitedViews,setVisitedViews] = useState<View[]>(['overview']);
  function navigate(next:View) {setView(next);setVisitedViews(current=>current.includes(next)?current:[...current,next]);}
  function closeView(target:View) {const index=visitedViews.indexOf(target);const remaining=visitedViews.filter(current=>current!==target);setVisitedViews(remaining);if(view===target)setView(remaining[Math.max(0,index-1)]??'overview');focusActiveTab.current=true;}
  const [platform,setPlatform] = useState('all'); const [topic,setTopic] = useState('all'); const [type,setType] = useState('all');
  const [query,setQuery] = useState(''); const [onlyFavorite,setOnlyFavorite] = useState(false); const [pool,setPool] = useState(false);
  const [sort,setSort] = useState('likes');
  const deferredQuery = useDeferredValue(query.trim().toLowerCase());
  const searchPending = query.trim().toLowerCase()!==deferredQuery;
  const [mobileDetail,setMobileDetail] = useState(false);
  const [selected,setSelected] = useState(''); const [tab,setTab] = useState('frames'); const [collectOpen,setCollectOpen] = useState(false);
  const [collectTrack,setCollectTrack]=useState<'daily'|'app_research'>('daily');
  const [busy,setBusy] = useState(false); const fileInput = useRef<HTMLInputElement>(null); const mainRef = useRef<HTMLElement>(null); const workspaceTabsRef = useRef<HTMLElement>(null); const focusActiveTab = useRef(false); const refreshVersion = useRef(0); const refreshAbort = useRef<AbortController|null>(null); const noteDrafts = useRef(new Map<string,string>());
  async function refresh(runId?:string) {
    const version=++refreshVersion.current;refreshAbort.current?.abort();const controller=new AbortController();refreshAbort.current=controller;setLoading(true);setError('');
    try {const next=await bootstrap(runId,controller.signal);if(version!==refreshVersion.current)return false;setData(next);if(next.run?.id!==data?.run?.id)setMobileDetail(false);return true;}
    catch(e) {if(version===refreshVersion.current){if(data)setNotice(`刷新失败：${(e as Error).message}，已保留当前数据。`);else setError((e as Error).message);}return false;}
    finally {if(version===refreshVersion.current)setLoading(false);}
  }
  useEffect(() => { void refresh();return ()=>{refreshVersion.current++;refreshAbort.current?.abort();}; },[]);
  useEffect(() => {
    const active=workspaceTabsRef.current?.querySelector<HTMLButtonElement>('[aria-current="page"]');
    const list=workspaceTabsRef.current;
    if(active&&list){
      const tabBounds=active.closest('.workspace-tab')!.getBoundingClientRect();
      const listBounds=list.getBoundingClientRect();
      if(tabBounds.left<listBounds.left)list.scrollLeft+=tabBounds.left-listBounds.left;
      else if(tabBounds.right>listBounds.right)list.scrollLeft+=tabBounds.right-listBounds.right;
    }
    if(focusActiveTab.current){active?.focus({preventScroll:true});focusActiveTab.current=false;}
  },[view,visitedViews.length]);
  useLayoutEffect(() => {
    const list=workspaceTabsRef.current;
    if(!list)return;
    const update=()=>{
      const active=list.querySelector<HTMLElement>('.workspace-tab.is-active');
      if(!active?.offsetWidth)return;
      list.style.setProperty('--workspace-tab-x',`${active.offsetLeft}px`);
      list.style.setProperty('--workspace-tab-y',`${active.offsetTop}px`);
      list.style.setProperty('--workspace-tab-width',`${active.offsetWidth}px`);
      list.style.setProperty('--workspace-tab-height',`${active.offsetHeight}px`);
      list.dataset.indicatorReady='true';
    };
    update();
    const observer=new ResizeObserver(update);
    observer.observe(list);
    list.querySelectorAll('.workspace-tab').forEach(tab=>observer.observe(tab));
    return ()=>observer.disconnect();
  },[view,visitedViews]);
  useEffect(() => { if (!notice) return; const timer=setTimeout(() => setNotice(''),4000); return () => clearTimeout(timer); },[notice]);
  const run = data?.run; const all = run?.items ?? emptyItems;
  useEffect(() => { mainRef.current?.scrollTo(0,0); window.scrollTo(0,0); },[view,run?.id]);
  useEffect(() => { if(window.matchMedia('(max-width:680px)').matches) window.scrollTo(0,0); },[mobileDetail]);
  const ranked = useMemo(() => new Set(run?.selectedIds ?? []),[run]);
  const searchableItems = useMemo(() => [...all].sort((a,b)=>sort==='newest'?Date.parse(b.capturedAt)-Date.parse(a.capturedAt):(b.metrics[sort==='comments'?'comments':'likes'].value??-1)-(a.metrics[sort==='comments'?'comments':'likes'].value??-1)).map(item=>({item,text:`${item.title} ${item.author} ${item.summary} ${item.audience.join(' ')}`.toLowerCase()})),[all,sort]);
  const items = useMemo(() => searchableItems.filter(({item:i,text}) => (pool || ranked.has(i.id)) && (platform === 'all' || i.platform === platform) && (topic === 'all' || i.topics.includes(topic as typeof topics[number])) && (type === 'all' || i.contentType === type) && (!onlyFavorite || data?.annotations[i.id]?.favorite) && text.includes(deferredQuery)).map(({item})=>item),[searchableItems,pool,ranked,platform,topic,type,onlyFavorite,data?.annotations,deferredQuery]);
  const hasFilters = platform!=='all' || topic!=='all' || type!=='all' || onlyFavorite || !!query;
  function resetFilters() {setPlatform('all');setTopic('all');setType('all');setOnlyFavorite(false);setQuery('');}
  function openLibrary() {resetFilters();setPool(true);setMobileDetail(false);navigate('library');}
  const item = items.find(i => i.id === selected) ?? items[0];
  const evidenceComments = all.flatMap(i => i.comments).filter(c => !c.isPromotion && !c.isAuthor).length;
  async function annotate(id:string, annotation:Annotation) { try { const saved=await api<Annotation>('annotations',{method:'POST',body:JSON.stringify({id,annotation})}); setData(d => d ? {...d,annotations:{...d.annotations,[id]:saved}} : d); setNotice('收藏与笔记已保存');return true; } catch(e) { setNotice((e as Error).message);return false; } }
  async function importFile(file?: File) { if (!file) return; setBusy(true); try { const imported=await api<Run>('import',{method:'POST',body:await file.text()}); if(await refresh(imported.id))setNotice('本地数据已导入'); } catch(e) { setNotice(`导入失败：${(e as Error).message}`); } finally { setBusy(false); if(fileInput.current) fileInput.current.value=''; } }
  function openEvidence(id:string, target='comments') { setPlatform('all');setTopic('all');setType('all');setQuery('');setOnlyFavorite(false);setPool(true);setSelected(id);setTab(target);setMobileDetail(true);navigate('library'); }
  return <div className={cn("app-shell",sidebarCollapsed&&"sidebar-collapsed")}>
    <header className="app-header"><div className="brand"><div className="brand-mark"><Activity size={20}/></div><strong>观澜<span>内容研究库</span></strong><span className="local-indicator"><i/>本地工作空间</span></div><nav className="header-breadcrumb" aria-label="页面路径"><span>研究工作区</span><ChevronRight size={13}/><strong>{viewLabels[view]}</strong></nav><div className="header-actions"><Button variant="ghost" size="icon" aria-label="刷新本地数据" onClick={() => void refresh(run?.id)} disabled={loading}><RefreshCw className={loading?'spin':''}/></Button><Button variant="outline" aria-label="导入数据" onClick={() => fileInput.current?.click()} disabled={busy}><Upload/><span className="import-label">导入</span></Button><Button onClick={() => {setCollectTrack('daily');setCollectOpen(true);}}><Plus/>新建采集</Button><input ref={fileInput} hidden type="file" accept="application/json,.json" onChange={e => void importFile(e.target.files?.[0])}/></div></header>
    <div className="app-body"><nav className="nav-rail" aria-label="主导航">
        <div className="rail-heading"><div className="rail-workspace-icon"><Layers3 size={18}/></div><div><strong>研究工作区</strong><span>内容与用户需求</span></div><Button variant="ghost" size="icon-sm" className="rail-collapse" aria-label={sidebarCollapsed?"展开侧栏":"收起侧栏"} aria-expanded={!sidebarCollapsed} aria-controls="workspace-navigation" onClick={()=>setSidebarCollapsed(!sidebarCollapsed)}>{sidebarCollapsed?<PanelLeftOpen/>:<PanelLeftClose/>}</Button></div>
        <div className="rail-navigation" id="workspace-navigation">{([
          {label:'研究分析',items:[{id:'overview',name:'总览',icon:LayoutGrid},{id:'library',name:'热点库',icon:Flame},{id:'needs',name:'需求洞察',icon:Lightbulb},{id:'apps',name:'App 调研',icon:Smartphone}]},
          {label:'数据管理',items:[{id:'runs',name:'采集记录',icon:ListChecks},{id:'timeline',name:'时间轴',icon:CalendarDays},{id:'settings',name:'采集设置',icon:Settings2}]},
        ] as const).map(group=><div className="rail-group" key={group.label}><div className="rail-group-label">{group.label}</div>{group.items.map(n=><Button key={n.id} variant="ghost" className={cn('nav-item',view===n.id&&'active')} aria-current={view===n.id?'page':undefined} title={n.name} onClick={()=>{navigate(n.id);if(n.id==='library')setMobileDetail(false);}}><n.icon/><span>{n.name}</span></Button>)}</div>)}</div>
        <div className="rail-footer"><ShieldCheck size={18}/><div><strong>本地工作空间</strong><span>数据仅保存在本机</span></div></div>
      </nav>
      <main ref={mainRef} aria-busy={loading} className={cn('main-area',view==='library' && 'library-layout')}>
        <nav ref={workspaceTabsRef} className="workspace-tabs" aria-label="已打开的页面"><span className="workspace-tab-indicator" aria-hidden="true"/>{visitedViews.map(openView=><div className={cn('workspace-tab',view===openView&&'is-active')} key={openView}><Button variant="ghost" aria-current={view===openView?'page':undefined} onClick={()=>{navigate(openView);if(openView==='library')setMobileDetail(false);}}>{viewLabels[openView]}</Button>{openView!=='overview'&&<Button variant="ghost" size="icon-xs" aria-label={`关闭${viewLabels[openView]}页签`} onClick={()=>closeView(openView)}><X/></Button>}</div>)}</nav>
        {error ? <Empty title="暂时无法读取本地数据">{error}<br/>请使用 pnpm dev 或 pnpm preview 启动本地工作空间。<Button variant="outline" onClick={() => void refresh(run?.id)} disabled={loading}>{loading?'正在加载…':'重新加载'}</Button></Empty> : loading && !data ? <Empty title="正在读取研究库" icon={<LoaderCircle className="spin"/>}/> : <>
          <section className="workspace-heading"><div><div className="eyebrow">研究工作台</div><h1>{viewLabels[view]}</h1><p>{view==='apps'?'聚焦小红书：主流产品与独立开发者，分开看产品发布和用户需求。':view==='timeline'?'按执行时间串联采集批次、研究结论与关注方向。':view==='overview'?'先看收集了什么，再看值得跟进的问题与内容机会。':view==='library'?'把热门内容、关键画面和真实反馈，放在一起研究。':view==='needs'?'保留用户原话，区分真实反馈与推广，把判断连接回证据。':view==='runs'?'查看采集范围、样本缺口和执行状态。':'Codex 负责采集和分析，工作空间负责保存与查看。'}</p></div>{view!=='timeline' && view!=='apps' && <div className="workspace-date">{loading?<LoaderCircle size={15} className="spin" aria-label="正在读取批次"/>:<CalendarDays size={15}/>} <FilterSelect label="选择采集批次" value={run?.id ?? ''} onValueChange={value=>void refresh(value)} options={data?.runs.length?data.runs.map(r=>({value:r.id,label:`${r.date} · ${r.mode==='historical_import'?'历史样本':`${r.track==='app_research'?'App 调研':'热点采集'} · ${statuses[r.status]}`} · ${r.id.slice(-6)}`})):[{value:'',label:'暂无采集批次'}]}/></div>}</section>
          {view!=='timeline' && view!=='apps' && <section className={cn("overview-strip",view!=="library"&&"dashboard-stats")}><div><div className="stat-icon lavender"><Clapperboard/></div><span>本批次入选内容<strong>{run?.selectedIds.length ?? 0}<small>{run?.mode==='historical_import'?'条历史样本':` / ${run?.track==='app_research'?run.config.appResearch.postsPerGroup*2:100} 目标`}</small></strong></span></div><div><div className="stat-icon rose"><MessageCircle/></div><span>已采集评论<strong>{all.reduce((n,i) => n+i.comments.length,0)}<small>条可见样本</small></strong></span></div><div><div className="stat-icon mint"><Target/></div><span>需求证据样本<strong>{evidenceComments}<small>排除已标记推广 / 作者</small></strong></span></div><div><div className="stat-icon amber"><ImageIcon/></div><span>本地内容画面<strong>{all.reduce((n,i) => n+i.frames.length,0)}<small>张截帧 / 图文</small></strong></span></div></section>}
          {view==='library' && <><div className="scope-note"><ShieldCheck size={14}/><span>{run?.mode==='historical_import'?'当前为此前采集的历史样本，未执行每日 Top 50 全量流程。':run?.track==='app_research'?`小红书近 ${run.config.appResearch.windowDays} 天的 App 调研样本，主流与独立产品各 ${run.config.appResearch.postsPerGroup} 条目标。`:`各平台近 ${run?.config.windowDays ?? data?.config.windowDays ?? 7} 天关键词候选池，按可见累计点赞各取前 50；并非全站热榜。`}</span><button onClick={() => navigate('runs')}>查看口径<ArrowRight size={12}/></button></div><div className={cn("research-workbench",mobileDetail&&"mobile-detail-open")}><aside className="content-library"><div className="library-toolbar"><h2>内容库 <span aria-live="polite">{items.length}</span></h2>{hasFilters&&<Button variant="ghost" size="xs" onClick={resetFilters}>清除筛选</Button>}<button className={cn('icon-button',onlyFavorite && 'is-on')} aria-label="仅看收藏" aria-pressed={onlyFavorite} onClick={() => setOnlyFavorite(!onlyFavorite)}><Bookmark size={16} fill={onlyFavorite?'currentColor':'none'}/></button></div><div className="platform-filter">{[['all','全部平台'],['douyin','抖音'],['xiaohongshu','小红书']].map(([value,label])=><button key={value} className={platform===value?'active':''} aria-pressed={platform===value} onClick={()=>setPlatform(value)}>{label}</button>)}</div><div className="search-field"><Search size={15}/><Input aria-label="搜索内容" placeholder="搜索标题、作者、内容…" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="library-selects"><FilterSelect label="方向筛选" value={topic} onValueChange={setTopic} options={[{value:'all',label:'全部方向'},...topics.map(t=>({value:t,label:t}))]}/><FilterSelect label="内容类型筛选" value={type} onValueChange={setType} options={[{value:'all',label:'全部类型'},...contentTypes.map(t=>({value:t,label:t}))]}/></div><div className="library-order"><FilterSelect label="内容排序" value={sort} onValueChange={setSort} options={[{value:'likes',label:'点赞最多'},{value:'comments',label:'评论最多'},{value:'newest',label:'最近采集'}]}/><FilterSelect label="内容范围" value={pool?'all':'ranked'} onValueChange={value=>setPool(value==='all')} options={[{value:'ranked',label:run?.track==='app_research'?'调研入选':'各平台 Top 50'},{value:'all',label:'全部候选'}]}/></div><div className="list-caption"><span aria-live="polite">{searchPending?'筛选中 · ':''}显示 {items.length} / {all.filter(i=>pool||ranked.has(i.id)).length} 条内容</span><span><ArrowDownWideNarrow size={13}/>{sort==='newest'?'采集时间':'累计互动'}降序</span></div><div className="content-list" aria-busy={searchPending}>{items.map(i=><button className={cn('content-row',item?.id===i.id && 'selected')} aria-pressed={item?.id===i.id} key={i.id} onClick={()=>{setSelected(i.id);setTab('frames');setMobileDetail(true);}}><div className="row-image"><FrameImage item={i}/><span className="format-icon">{i.format==='video'?<Play size={11}/>:<ImageIcon size={11}/>}</span></div><div className="row-body"><div className="row-platform"><Platform platform={i.platform}/><span>{i.contentType}</span></div><h3>{i.title}</h3><p className="row-takeaway"><span>看点</span>{i.analysis.hypotheses[0]?.title || i.analysis.hook || i.summary || '内容待分析'}</p><p>{i.author}</p><div className="row-metrics"><span><Heart size={12}/><span className="sr-only">点赞</span>{i.metrics.likes.display || number(i.metrics.likes.value)}</span><span><MessageCircle size={12}/><span className="sr-only">评论</span>{i.metrics.comments.display || number(i.metrics.comments.value)}</span><span>{i.publishedText || '日期未确认'}</span></div></div></button>)}{!items.length&&<Empty title="还没有匹配的内容">{all.length?'调整平台、分类或搜索条件。':'点击新建采集，将任务交给 Codex；也可导入本地批次 JSON。'}{hasFilters&&<Button variant="outline" onClick={resetFilters}>清除筛选</Button>}</Empty>}</div><div className="library-bottom"><Database size={12}/><span>本地保存 · 刷新读取最新采集</span></div></aside>
            <section className="detail-workspace"><div className="mobile-detail-toolbar"><Button variant="ghost" onClick={()=>setMobileDetail(false)}><ArrowLeft/>返回内容库</Button></div>{item ? <ContentDetail key={item.id} item={item} noteDrafts={noteDrafts.current} annotation={data?.annotations[item.id] ?? {favorite:false,note:''}} onAnnotate={a=>annotate(item.id,a)} tab={tab} setTab={setTab} notify={setNotice}/> : <Empty title="从左侧选择一条内容" icon={<LayoutGrid size={34}/>}>查看关键画面、传播拆解和评论需求。</Empty>}</section></div></>}
          {view==='overview' && <OverviewView run={run} isLatest={run?.id===data?.runs[0]?.id} openContent={openEvidence} onLibrary={openLibrary} onNeeds={()=>navigate('needs')} onRuns={()=>navigate('runs')} onCollect={()=>{setCollectTrack('daily');setCollectOpen(true);}}/>}
          {view==='needs' && <NeedsView items={all} report={run?.report} openEvidence={openEvidence}/>}
          {view==='apps' && data && <AppResearchView entries={data.appResearchItems ?? []} config={data.config.appResearch} onCollect={()=>{setCollectTrack('app_research');setCollectOpen(true);}} onOpen={async(runId,itemId,target)=>{if(await refresh(runId))openEvidence(itemId,target);}}/>}
          {view==='timeline' && <TimelineView runs={data?.runs ?? []} onSelect={(id,target)=>{void refresh(id);navigate(target);}}/>}
          {view==='runs' && <RunsView data={data} onSelect={id=>{void refresh(id);navigate('library');}}/>}
          {view==='settings' && data && <SettingsView key={JSON.stringify(data.config)} config={data.config} onSave={async config=>{await api('config',{method:'POST',body:JSON.stringify(config)});setData({...data,config});setNotice('采集设置已保存，下次 Codex 执行时生效');}}/>}
        </>}
      </main>
    </div>
    {notice&&<div className="notice" role="status"><Check size={16}/>{notice}<button aria-label="关闭提示" onClick={()=>setNotice('')}><X size={14}/></button></div>}
    <CollectDialog key={collectTrack} track={collectTrack} open={collectOpen} onOpenChange={setCollectOpen} config={data?.config} onCreated={r=>{setData(d=>d?{...d,requests:[r,...d.requests]}:d);}} notify={setNotice}/>
  </div>;
}

const CommentRow = memo(function CommentRow({comment:c,index}: {comment:ContentItem['comments'][number];index:number}) {
  return <div className="comment-row"><div className="comment-avatar">{String(index+1).padStart(2,'0')}</div><div><div className="comment-meta"><span>{c.parentId?'楼中楼回复':'用户评论'}{c.isAuthor?' · 作者':''}</span>{c.isPromotion&&<Badge variant="outline">推广待核实</Badge>}<span>{c.publishedText}</span></div><p>{c.text}</p><div className="comment-bottom">{c.tags.map(t=><Badge key={t} variant="outline">{t}</Badge>)}<span><Heart size={12}/>{number(c.likes)}</span></div></div></div>;
});

function ContentDetail({item,annotation,onAnnotate,tab,setTab,notify,noteDrafts}: {item:ContentItem;annotation:Annotation;noteDrafts:Map<string,string>;onAnnotate:(a:Annotation)=>Promise<boolean>;tab:string;setTab:(t:string)=>void;notify:(s:string)=>void}) {
  const [preview,setPreview] = useState<ContentItem['frames'][number] | null>(null); const [notes,setNotes] = useState(()=>noteDrafts.get(item.id)??annotation.note); const [savingNotes,setSavingNotes] = useState(false);
  const notesChanged = notes!==annotation.note;
  async function saveNotes() {if(savingNotes||!notesChanged)return;const submitted=notes;setSavingNotes(true);try{if(await onAnnotate({...annotation,note:submitted})){if(noteDrafts.get(item.id)===submitted)noteDrafts.delete(item.id);}}finally{setSavingNotes(false);}}
  function movePreview(direction:number) {setPreview(current=>{const index=item.frames.findIndex(frame=>frame.id===current?.id);return index<0?current:item.frames[index+direction]??current;});}
  const previewIndex = item.frames.findIndex(frame=>frame.id===preview?.id);
  const [commentQuery,setCommentQuery] = useState(''); const [showPromotion,setShowPromotion] = useState(false); const [showAuthor,setShowAuthor] = useState(false);
  const deferredCommentQuery = useDeferredValue(commentQuery.trim().toLowerCase());
  const [commentLimit,setCommentLimit] = useState(50);
  useEffect(()=>setCommentLimit(50),[deferredCommentQuery,showPromotion,showAuthor]);
  const comments = useMemo(()=>item.comments.filter(c=>(showPromotion||!c.isPromotion)&&(showAuthor||!c.isAuthor)&&c.text.toLowerCase().includes(deferredCommentQuery)),[item.comments,showPromotion,showAuthor,deferredCommentQuery]);
  const evidenceText = useMemo(()=>new Map<string,string>([...item.comments.map(c=>[c.id,c.text] as const),...item.frames.map(f=>[f.id,f.caption] as const)]),[item.comments,item.frames]);
  const evidence = (id:string) => evidenceText.get(id) ?? (id==='metrics'?'采集时可见互动指标':id==='title'?'内容标题':id==='body'?'笔记正文':`未找到证据：${id}`);
  return <>
    <div className="content-header"><div className="content-kicker"><Platform platform={item.platform}/><span>{item.format==='video'?'视频':item.format==='image_note'?'图文笔记':'帖子'}</span><span>发布：{item.publishedText || item.publishedAt || '未确认'}</span></div><div className="title-line"><h2>{item.title}</h2><Button variant="ghost" size="icon" aria-label={annotation.favorite?'取消收藏':'收藏内容'} disabled={savingNotes} onClick={()=>onAnnotate({...annotation,favorite:!annotation.favorite})}><Bookmark fill={annotation.favorite?'currentColor':'none'}/></Button></div><div className="author-line"><span className="author-avatar">{item.author.slice(0,1)}</span>{item.author}<span>采集于 {new Date(item.capturedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</span><a href={item.url} target="_blank" rel="noreferrer">查看原帖<ExternalLink size={12}/></a></div><div className="content-tags">{item.topics.map(t=><Badge key={t} variant="secondary">{t}</Badge>)}<Badge variant="outline">{item.contentType}</Badge>{item.audience.map(t=><Badge key={t} variant="outline">{t}</Badge>)}</div>{item.appResearch&&<div className="app-content-context"><Smartphone size={13}/><span>{item.appResearch.appNames.join(' / ')||'产品名待确认'}</span><Badge variant="outline">{item.appResearch.postType}</Badge>{item.appResearch.classificationEvidence&&<span title={item.appResearch.classificationEvidence}>{item.appResearch.productGroup==='indie'?'独立产品':item.appResearch.productGroup==='mainstream'?'主流产品观察':'归属待核实'}</span>}</div>}<div className="content-metrics"><Metric label="点赞" metric={item.metrics.likes} icon={<Heart size={13}/>}/><Metric label="收藏" metric={item.metrics.saves} icon={<Bookmark size={13}/>}/><Metric label="评论" metric={item.metrics.comments} icon={<MessageCircle size={13}/>}/><Metric label="分享" metric={item.metrics.shares} icon={<ArrowRight size={13}/>}/></div></div>
    <Tabs value={tab} onValueChange={value=>setTab(String(value))} className="detail-tabs"><TabsList variant="line"><TabsTrigger value="frames"><ImageIcon/>内容画面<span>{item.frames.length}</span></TabsTrigger><TabsTrigger value="analysis"><Sparkles/>传播拆解</TabsTrigger><TabsTrigger value="comments"><MessageCircle/>评论与需求<span>{item.comments.length}</span></TabsTrigger><TabsTrigger value="notes"><FileText/>研究笔记</TabsTrigger></TabsList>
      <TabsContent value="frames"><div className="reading-guide" aria-label="内容重点"><section className="reading-card reading-content"><div className="reading-label"><Clapperboard size={14}/><span>01 · 内容在讲什么</span></div><p>{item.summary || '内容尚未完整观察，等待补充。'}</p></section><button className="reading-card reading-reason" onClick={()=>setTab('analysis')}><div className="reading-label"><Sparkles size={14}/><span>02 · 传播看点</span><ArrowRight size={13}/></div><h3>{item.analysis.hypotheses[0]?.title || '传播原因待分析'}</h3><p>{item.analysis.hypotheses[0]?.explanation || item.analysis.hook || '需要结合内容和互动证据判断。'}</p><span className="reading-footnote">传播假设 · 查看依据</span></button><button className="reading-card reading-need" onClick={()=>setTab('comments')}><div className="reading-label"><MessageCircle size={14}/><span>03 · 用户关注什么</span><ArrowRight size={13}/></div><h3>{item.analysis.needs[0]?.title || (item.comments.length ? '评论需求待归纳' : '暂无评论样本')}</h3><p>{item.analysis.needs[0]?.description || (item.comments.length ? '查看已采集的用户原话，寻找问题与需求。' : '采集评论后再判断用户关注点。')}</p><span className="reading-footnote">{item.analysis.needs.length} 项需求 · {item.comments.length} 条评论样本</span></button></div><div className="panel-heading"><div><h3>关键画面</h3><p>点击放大，查看时间点与画面观察。</p></div><Badge variant="outline">{item.duration != null?`${item.duration} 秒`:`${item.frames.length} 张已采集`}</Badge></div>{item.frames.length?<div className="frame-grid">{item.frames.map((f,index)=><button key={f.id} className="frame-card" onClick={()=>setPreview(f)}><div className="frame-image"><img src={assetUrl(f.path)} alt={f.caption} loading="lazy"/><span>{f.kind==='video_frame'?`${f.timestamp?.toFixed(1) ?? '—'}s`:f.kind==='note_image'?`图 ${index+1}`:'页面证据'}</span><span className="frame-expand"><ImageIcon size={14}/></span></div><h4>{f.caption}</h4><p>{f.observed || '画面观察待补充'}</p></button>)}</div>:<Empty title="这条内容还没有采集画面">下次运行 Skill 时补充视频截帧或图文截图。</Empty>}{item.analysis.structure.length>0&&<div className="structure-strip">{item.analysis.structure.map((s,index)=><div key={index}><span>{String(index+1).padStart(2,'0')}</span><h4>{s.label}</h4><p>{s.description}</p></div>)}</div>}</TabsContent>
      <TabsContent value="analysis"><div className="panel-heading"><div><h3>为什么获得互动</h3><p>把画面、互动和评论作为证据，以下为传播假设。</p></div><Badge variant="outline">{item.analysis.status==='complete'?'已分析':item.analysis.status==='partial'?'部分分析':'待分析'}</Badge></div><div className="hook-card"><Sparkles size={20}/><div><h4>内容钩子</h4><p>{item.analysis.hook||'尚未观察到明确钩子'}</p></div></div><div className="hypothesis-list">{item.analysis.hypotheses.map((h,index)=><Card key={index}><CardHeader><CardTitle><span className="analysis-number">0{index+1}</span>{h.title}</CardTitle><Badge variant="secondary" className={`confidence confidence-${h.confidence}`}>{h.confidence==='high'?'证据较充分':h.confidence==='medium'?'中等把握':'待验证'}</Badge></CardHeader><CardContent><p>{h.explanation}</p><div className="evidence-box"><span>支持这个判断的证据</span>{h.evidenceIds.map(id=><p key={id}>{evidence(id)}</p>)}</div>{h.alternative&&<p className="alternative">其他可能：{h.alternative}</p>}</CardContent></Card>)}</div>{!item.analysis.hypotheses.length&&<Empty title="传播分析待补充">Codex 需要先观察内容和互动证据。</Empty>}<div className="limitations"><ShieldCheck size={16}/><div><strong>结论边界</strong>{[...item.analysis.limitations,...item.analysis.healthClaims.map(c=>`待核实健康主张：${c}`)].map((l,i)=><p key={i}>{l}</p>)}<p>未获得曝光、完播与投流数据，不能据此证明推荐原因或训练有效性。</p></div></div></TabsContent>
      <TabsContent value="comments"><div className="panel-heading"><div><h3>评论里的人在关心什么</h3><p>采集 {item.comments.length} 条 / 页面显示 {number(item.commentSampling.displayedTotal)} 条 · {item.commentSampling.strategy}</p></div><Badge variant="outline">{item.commentSampling.readStatus==='all_visible'?'已读完当前可见评论':item.commentSampling.readStatus==='blocked'?'评论读取受阻':'评论尚未读完'}</Badge></div>{item.analysis.needs.length>0&&<div className="need-cards">{item.analysis.needs.map(n=><Card key={n.id}><CardHeader><CardTitle>{n.title}</CardTitle><Badge variant="secondary" className={`priority priority-${n.priority}`}>{n.priority}</Badge></CardHeader><CardContent><p>{n.description}</p><div className="need-opportunity"><Lightbulb size={14}/><div><strong>可以怎么做</strong>{n.opportunity}</div></div>{n.commentIds.map(id=><blockquote key={id}>{evidence(id)}</blockquote>)}</CardContent></Card>)}</div>}<div className="comment-controls"><div className="search-field"><Search size={14}/><Input aria-label="搜索评论" placeholder="搜索评论原文…" value={commentQuery} onChange={e=>setCommentQuery(e.target.value)}/></div><label><Checkbox checked={showPromotion} onCheckedChange={setShowPromotion}/>包含推广</label><label><Checkbox checked={showAuthor} onCheckedChange={setShowAuthor}/>包含作者</label></div><div className="comment-result-count" role="status">{commentQuery.trim().toLowerCase()!==deferredCommentQuery?'正在筛选评论…':`显示 ${Math.min(commentLimit,comments.length)} / ${comments.length} 条匹配评论`}{commentQuery&&<Button variant="ghost" size="xs" onClick={()=>setCommentQuery('')}>清除搜索<X/></Button>}</div><div className="comments-list" aria-busy={commentQuery.trim().toLowerCase()!==deferredCommentQuery}>{comments.slice(0,commentLimit).map((comment,index)=><CommentRow key={comment.id} comment={comment} index={index}/>)}{!comments.length&&<Empty title="没有符合条件的评论">未采到的评论不会用推测补充。</Empty>}</div>{comments.length>commentLimit&&<div className="comment-load-more"><Button variant="outline" onClick={()=>setCommentLimit(limit=>limit+50)}>再显示 {Math.min(50,comments.length-commentLimit)} 条评论<ChevronDown/></Button><span>还有 {comments.length-commentLimit} 条匹配评论</span></div>}<div className="limitations"><ShieldCheck size={15}/><div>{item.commentSampling.stopReason&&<p>{item.commentSampling.stopReason}</p>}{item.commentSampling.limitations.map((l,i)=><p key={i}>{l}</p>)}</div></div></TabsContent>
      <TabsContent value="notes"><div className="panel-heading"><div><h3>我的研究笔记</h3><p aria-live="polite">{savingNotes?'正在保存…':notesChanged?'有未保存的修改，切换内容时保留草稿。':'已保存到本机。'}</p></div><Button variant="outline" disabled={savingNotes||!notesChanged} onClick={()=>void saveNotes()}>{savingNotes?<LoaderCircle className="spin"/>:<Check/>}{savingNotes?'保存中…':notesChanged?'保存笔记':'已保存'}</Button></div><Textarea aria-label="研究笔记" className="notes-editor" placeholder="记录你的判断、值得跟进的问题，或者可复用的内容结构…" value={notes} onChange={e=>{setNotes(e.target.value);if(e.target.value===annotation.note)noteDrafts.delete(item.id);else noteDrafts.set(item.id,e.target.value);}} onKeyDown={e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();void saveNotes();}}}/><div className="provenance"><h4>来源与采集口径</h4><p>关键词：{item.discovery.keywords.join('、')}</p><p>排序：{item.discovery.sort} · 时间：{item.discovery.timeWindow}</p><p>{item.discovery.scope}</p><a href={item.discovery.sourceUrl} target="_blank" rel="noreferrer">打开发现来源<ExternalLink size={12}/></a><Button variant="outline" onClick={()=>download(`${item.platform}-${item.platformId}.json`,item)}><Download/>导出此条 JSON</Button></div></TabsContent>
    </Tabs>
    <Dialog open={!!preview} onOpenChange={open=>{if(!open)setPreview(null);}}><DialogContent className="image-dialog" onKeyDown={e=>{if((e.target as HTMLElement).closest('input,textarea,[contenteditable="true"]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();movePreview(e.key==='ArrowLeft'?-1:1);}}}><DialogHeader><DialogTitle>{preview?.caption}</DialogTitle><DialogDescription>{preview?.observed || '本地保存的内容画面'}</DialogDescription></DialogHeader>{preview&&<PreviewImage key={preview.path} path={preview.path} caption={preview.caption}/>}<div className="preview-navigation"><Button variant="outline" disabled={previewIndex<=0} onClick={()=>movePreview(-1)}><ArrowLeft/>上一张</Button><span aria-live="polite">{previewIndex+1} / {item.frames.length}</span><Button variant="outline" disabled={previewIndex<0||previewIndex>=item.frames.length-1} onClick={()=>movePreview(1)}>下一张<ArrowRight/></Button></div></DialogContent></Dialog>
  </>;
}

function OverviewView({run,isLatest,openContent,onLibrary,onNeeds,onRuns,onCollect}: {run:Run|null|undefined;isLatest:boolean;openContent:(id:string,target?:string)=>void;onLibrary:()=>void;onNeeds:()=>void;onRuns:()=>void;onCollect:()=>void}) {
  if (!run) return <div className="page-content"><Empty title="从第一批内容开始研究" icon={<LayoutGrid size={32}/>}>采集后，这里会汇总最新内容、研究结论和需要关注的问题。<Button onClick={onCollect}><Plus/>新建采集</Button></Empty></div>;
  const items=run.items;
  const recent=[...items].sort((a,b)=>Date.parse(b.capturedAt)-Date.parse(a.capturedAt)).slice(0,6);
  type Focus={title:string;description:string;priority:'P0'|'P1'|'P2';opportunity:string;sourceItem:ContentItem;sources:{item:ContentItem;comment:ContentItem['comments'][number]}[]};
  const focusByTitle=new Map<string,Focus>();
  for (const item of items) for (const need of item.analysis.needs) {
    const evidence=item.comments.filter(c=>need.commentIds.includes(c.id)&&!c.isAuthor&&!c.isPromotion);
    if (!evidence.length) continue;
    let focus=focusByTitle.get(need.title);
    if (!focus) {focus={title:need.title,description:need.description,priority:need.priority,opportunity:need.opportunity,sourceItem:item,sources:[]};focusByTitle.set(need.title,focus);}
    if (need.priority<focus.priority) {focus.priority=need.priority;focus.sourceItem=item;focus.description=need.description;focus.opportunity=need.opportunity;}
    for (const comment of evidence) if (!focus.sources.some(s=>s.item.id===item.id&&s.comment.id===comment.id)) focus.sources.push({item,comment});
  }
  const focuses=[...focusByTitle.values()].sort((a,b)=>a.priority.localeCompare(b.priority)||b.sources.length-a.sources.length);
  const distribution=[...new Set(items.map(item=>item.contentType))].map(type=>({type,count:items.filter(item=>item.contentType===type).length})).sort((a,b)=>b.count-a.count);
  const collectedAt=recent[0]?.capturedAt??run.finishedAt??run.startedAt;
  return <div className="page-content overview-page">
    <div className="dashboard-analysis">
      <Card className="sample-distribution"><CardHeader><div><CardTitle>内容样本分布</CardTitle><p className="dashboard-description">本批次 {items.length} 条内容 · 按内容类型统计</p></div><Badge variant="outline">{run.mode==='historical_import'?'历史样本':'采集快照'}</Badge></CardHeader><CardContent><div className="distribution-platforms">{(['douyin','xiaohongshu'] as const).map(platform=><span key={platform}><Platform platform={platform}/><strong>{items.filter(item=>item.platform===platform).length}</strong><span>条</span></span>)}</div>{distribution.length?<div className="distribution-bars">{distribution.map(({type,count})=><div className="distribution-row" key={type}><span>{type}</span><div className="distribution-track"><div style={{width:`${count/items.length*100}%`}}/></div><strong>{count}<small> / {items.length}</small></strong></div>)}</div>:<p className="dashboard-description">暂无内容，采集完成后显示分布。</p>}<p className="distribution-note">展示已采集样本的构成，不代表平台整体占比。</p></CardContent></Card>
      <Card className="dashboard-summary"><CardHeader><CardTitle>本批次研究摘要</CardTitle><Badge variant="outline">{run.mode==='historical_import'?'历史导入':statuses[run.status]}</Badge></CardHeader><CardContent><h2>{run.report.summary||`已收集 ${items.length} 条内容，${focuses.length} 项有评论证据的需求`}</h2>{run.report.findings.length?<ul>{run.report.findings.slice(0,3).map((finding,index)=><li key={index}>{finding}</li>)}</ul>:<p className="dashboard-description">跨内容的研究结论等待整理。</p>}<div className="dashboard-summary-footer"><span>采集于 {new Date(collectedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</span><Button variant="ghost" size="sm" onClick={onRuns}>采集记录<ArrowRight/></Button></div></CardContent></Card>
    </div>
    <div className="overview-columns"><section className="recent-section"><div className="overview-section-heading"><div><h2><Clapperboard size={17}/>最近收集的内容</h2><p>按实际采集时间排列，点击查看内容和画面。</p></div><button onClick={onLibrary}>全部 {items.length} 条<ArrowRight size={13}/></button></div><div className="dashboard-content-table"><Table><TableHeader><TableRow><TableHead>内容 / 作者</TableHead><TableHead>平台</TableHead><TableHead>类型</TableHead><TableHead className="text-right">点赞</TableHead><TableHead className="text-right">评论</TableHead><TableHead className="text-right">已采评论</TableHead><TableHead>采集时间</TableHead><TableHead><span className="sr-only">查看内容</span></TableHead></TableRow></TableHeader><TableBody>{recent.map(item=><TableRow key={item.id}><TableCell data-label="内容 / 作者"><div className="dashboard-content-title"><div className="dashboard-thumbnail"><FrameImage item={item}/></div><div><button onClick={()=>openContent(item.id,'frames')}>{item.title}</button><span>{item.author}</span></div></div></TableCell><TableCell data-label="平台"><Platform platform={item.platform}/></TableCell><TableCell data-label="类型"><Badge variant="outline">{item.contentType}</Badge></TableCell><TableCell data-label="点赞" className="text-right tabular-nums">{item.metrics.likes.display||number(item.metrics.likes.value)}</TableCell><TableCell data-label="评论" className="text-right tabular-nums">{item.metrics.comments.display||number(item.metrics.comments.value)}</TableCell><TableCell data-label="已采评论" className="text-right tabular-nums">{item.comments.length}</TableCell><TableCell data-label="采集时间" className="whitespace-nowrap text-muted-foreground">{new Date(item.capturedAt).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}</TableCell><TableCell><Button variant="ghost" size="icon-sm" aria-label={`查看${item.title}`} onClick={()=>openContent(item.id,'frames')}><ArrowRight/></Button></TableCell></TableRow>)}</TableBody></Table>{!recent.length&&<Empty title="本批次还没有内容">采集完成后会在这里显示。</Empty>}</div></section>
    <section className="attention-section"><div className="overview-section-heading"><div><h2><Target size={17}/>需要优先关注</h2><p>按研究优先级与已采样证据数排序。</p></div><button onClick={onNeeds}>全部需求<ArrowRight size={13}/></button></div><div className="attention-list">{focuses.slice(0,3).map((focus,index)=><article className="attention-card" key={focus.title}><div className="attention-card-title"><span className="attention-number">0{index+1}</span><h3>{focus.title}</h3><Badge variant="secondary" className={`priority priority-${focus.priority}`}>{focus.priority}</Badge></div><p>{focus.description}</p><button className="attention-quote" onClick={()=>openContent(focus.sources[0].item.id,'comments')}><MessageCircle size={13}/><span>“{focus.sources[0].comment.text}”</span></button><div className="attention-action"><Lightbulb size={14}/><div><span>建议关注</span><p>{focus.opportunity}</p></div></div><div className="attention-footer"><span>{focus.sources.length} 条用户原话 · {new Set(focus.sources.map(s=>s.item.id)).size} 条内容</span><button onClick={()=>openContent(focus.sourceItem.id,'comments')}>查看证据<ArrowRight size={12}/></button></div></article>)}{!focuses.length&&<div className="attention-empty"><Lightbulb size={24}/><h3>关注点等待评论证据</h3><p>尚未发现有可见用户评论支持的需求，不用推测填充。</p></div>}</div><p className="attention-caveat">优先级为研究判断，评论样本不代表市场需求占比。</p></section></div>
    {run.report.opportunities.length>0&&<section className="overview-next"><div className="overview-section-heading"><div><h2><Lightbulb size={17}/>接下来可以做什么</h2><p>来自本批次分析的内容选题与产品验证建议。</p></div></div><div>{run.report.opportunities.map((opportunity,index)=><p key={index}><span>{String(index+1).padStart(2,'0')}</span>{opportunity}</p>)}</div></section>}
    {run.report.limitations.length>0&&<details className="overview-boundaries"><summary><ShieldCheck size={13}/>样本范围与结论边界<span>{run.report.limitations.length} 项说明</span></summary>{run.report.limitations.map((limitation,index)=><p key={index}>{limitation}</p>)}</details>}
  </div>;
}

function NeedsView({items,report,openEvidence}: {items:ContentItem[];report?:Run['report'];openEvidence:(id:string)=>void}) {
  const [query,setQuery]=useState(''); const [priority,setPriority]=useState('all');
  const deferredQuery=useDeferredValue(query.trim().toLowerCase());
  const evidenceNeeds=useMemo(()=>items.flatMap(item=>item.analysis.needs.map(need=>({item,need,comments:item.comments.filter(c=>need.commentIds.includes(c.id)&&!c.isPromotion&&!c.isAuthor)}))).sort((a,b)=>a.need.priority.localeCompare(b.need.priority)||b.comments.length-a.comments.length),[items]);
  const needs=useMemo(()=>evidenceNeeds.filter(n=>(priority==='all'||n.need.priority===priority)&&`${n.need.title} ${n.need.description} ${n.need.opportunity}`.toLowerCase().includes(deferredQuery)),[evidenceNeeds,priority,deferredQuery]);
  return <div className="page-content">{report?.summary&&<details className="needs-summary"><summary>本批次研究摘要 · {report.summary}</summary>{report.findings.map((f,i)=><p key={i}>{f}</p>)}</details>}<div className="needs-toolbar"><h2>需求证据 <span aria-live="polite">{needs.length}</span></h2><div className="search-field"><Search size={15}/><Input aria-label="搜索需求" placeholder="搜索需求、痛点、机会…" value={query} onChange={e=>setQuery(e.target.value)}/></div><FilterSelect label="需求优先级" value={priority} onValueChange={setPriority} options={[{value:'all',label:'全部优先级'},...['P0','P1','P2'].map(value=>({value,label:value}))]}/>{(query||priority!=='all')&&<Button variant="ghost" size="sm" onClick={()=>{setQuery('');setPriority('all');}}>清除筛选</Button>}</div><p className="subtle">优先级是研究判断；证据数量指当前已采样评论，不等于市场需求人数。</p><div className="insights-grid">{needs.map(({item,need,comments})=><Card key={`${item.id}:${need.id}`}><CardHeader><CardTitle>{need.title}</CardTitle><Badge variant="secondary" className={`priority priority-${need.priority}`}>{need.priority}</Badge></CardHeader><CardContent><span className="need-source">来源：{item.title}</span><p>{need.description}</p><div className="need-opportunity"><Lightbulb size={15}/><div><strong>可以怎么做</strong>{need.opportunity}</div></div>{comments.slice(0,3).map(c=><blockquote key={c.id}>{c.text}</blockquote>)}<div className="insight-footer"><Platform platform={item.platform}/><span>{comments.length} 条可见用户证据</span><button onClick={()=>openEvidence(item.id)}>查看上下文<ArrowRight size={13}/></button></div></CardContent></Card>)}</div>{!needs.length&&<Empty title={query||priority!=='all'?'没有匹配的需求':'需求仍在等待证据'}>{query||priority!=='all'?'调整搜索词或优先级筛选。':'采集评论并完成分析后，这里会显示可追溯的用户需求。'}</Empty>}{!!report?.limitations.length&&<div className="limitations"><ShieldCheck size={16}/><div>{report.limitations.map((l,i)=><p key={i}>{l}</p>)}</div></div>}</div>;
}
function AppResearchView({entries,config,onCollect,onOpen}: {entries:Bootstrap['appResearchItems'];config:Config['appResearch'];onCollect:()=>void;onOpen:(runId:string,itemId:string,target:string)=>Promise<void>}) {
  const [group,setGroup]=useState('all');const [postType,setPostType]=useState('all');const [query,setQuery]=useState('');
  const productGroupRef=useRef<HTMLDivElement>(null);
  useLayoutEffect(()=>{
    const container=productGroupRef.current;
    if(!container)return;
    const update=()=>{
      const active=container.querySelector<HTMLElement>('[aria-pressed="true"]');
      if(!active?.offsetWidth)return;
      container.style.setProperty('--filter-x',`${active.offsetLeft}px`);
      container.style.setProperty('--filter-y',`${active.offsetTop}px`);
      container.style.setProperty('--filter-width',`${active.offsetWidth}px`);
      container.style.setProperty('--filter-height',`${active.offsetHeight}px`);
      container.dataset.indicatorReady='true';
    };
    update();
    const observer=new ResizeObserver(update);
    observer.observe(container);
    container.querySelectorAll('button').forEach(button=>observer.observe(button));
    return()=>observer.disconnect();
  },[group]);
  const deferredQuery=useDeferredValue(query.trim().toLowerCase());
  const samples=useMemo(()=>entries.filter(e=>e.item.platform==='xiaohongshu').sort((a,b)=>Date.parse(b.item.capturedAt)-Date.parse(a.item.capturedAt)),[entries]);
  const filtered=useMemo(()=>samples.filter(({item})=>(group==='all'||item.appResearch?.productGroup===group)&&(postType==='all'||item.appResearch?.postType===postType)&&`${item.title} ${item.summary} ${item.appResearch?.appNames.join(' ')??''} ${item.appResearch?.dimensions.join(' ')??''}`.toLowerCase().includes(deferredQuery)),[samples,group,postType,deferredQuery]);
  const userComments=samples.flatMap(e=>e.item.comments).filter(c=>!c.isAuthor&&!c.isPromotion);
  const needs=filtered.flatMap(({item,runId})=>item.analysis.needs.map(need=>({item,runId,need,evidence:item.comments.filter(c=>need.commentIds.includes(c.id)&&!c.isAuthor&&!c.isPromotion)}))).filter(row=>row.evidence.length>0).sort((a,b)=>a.need.priority.localeCompare(b.need.priority)||b.evidence.length-a.evidence.length);
  const focus=needs.filter((row,index)=>needs.findIndex(other=>other.need.title===row.need.title)===index).slice(0,3);
  const groupName={mainstream:'国内主流产品',indie:'独立开发者产品',unknown:'归属待核实'};
  return <div className="page-content app-research-page"><div className="app-research-intro"><div><div className="eyebrow"><Smartphone size={14}/>小红书 · 产品与需求研究</div><h2>主流产品看痛点，独立产品看机会</h2><p>跨批次汇集已采集的最新帖子快照，区分用户反馈、产品对比与开发者发布。</p></div><Button onClick={onCollect}><Plus/>新建 App 调研</Button></div><div className="app-research-stats"><div><span>主流产品帖子</span><strong>{samples.filter(e=>e.item.appResearch?.productGroup==='mainstream').length}</strong></div><div><span>独立产品帖子</span><strong>{samples.filter(e=>e.item.appResearch?.productGroup==='indie').length}</strong></div><div><span>用户反馈 / 求推荐</span><strong>{samples.filter(e=>['用户反馈','求推荐'].includes(e.item.appResearch?.postType??'')).length}</strong></div><div><span>非推广、非作者评论样本</span><strong>{userComments.length}</strong></div></div><div className="app-watchlist"><span>主流产品观察清单</span>{config.mainstreamApps.map(name=><Badge variant="outline" key={name}>{name}</Badge>)}<small>用于定向检索，不代表市场排名。</small></div><div className="app-research-toolbar"><div ref={productGroupRef} className="platform-filter sliding-filter" role="group" aria-label="产品分组"><span className="platform-filter-indicator" aria-hidden="true"/>{[['all','全部产品'],['mainstream','国内主流'],['indie','独立开发者'],['unknown','待核实']].map(([value,label])=><Button variant="ghost" key={value} className={group===value?'active':''} aria-pressed={group===value} onClick={()=>setGroup(value)}>{label}</Button>)}</div><div className="search-field"><Search size={14}/><Input placeholder="搜索 App、帖子、功能痛点…" value={query} onChange={e=>setQuery(e.target.value)}/></div><FilterSelect label="App帖子类型" value={postType} onValueChange={setPostType} options={[{value:'all',label:'全部帖子类型'},...appPostTypes.map(type=>({value:type,label:type}))]}/></div>{focus.length>0&&<section className="app-focus-section"><h3>当前样本里值得关注的需求</h3><div>{focus.map(({item,runId,need,evidence})=><button key={need.title} onClick={()=>void onOpen(runId,item.id,'comments')}><span><Target size={13}/>{need.title}<Badge variant="secondary" className={`priority priority-${need.priority}`}>{need.priority}</Badge></span><p>{need.description}</p><small>{evidence.length} 条可见评论证据<ArrowRight size={12}/></small></button>)}</div></section>}<div className="overview-section-heading"><div><h2>帖子与评论样本 <span>{filtered.length}</span></h2><p>按采集时间排序，同一帖子保留最新快照；开发者发帖不计作真实用户需求证据。</p></div></div><div className="app-post-grid">{filtered.map(({item,runId})=><Card key={item.id}><CardHeader><div className="app-post-labels"><Platform platform={item.platform}/><Badge variant="secondary">{item.appResearch?groupName[item.appResearch.productGroup]:'归属待核实'}</Badge><Badge variant="outline">{item.appResearch?.postType??'其他'}</Badge></div><CardTitle><button onClick={()=>void onOpen(runId,item.id,'frames')}>{item.title}<ArrowRight size={14}/></button></CardTitle></CardHeader><CardContent><div className="app-post-body"><div className="recent-thumbnail"><FrameImage item={item}/></div><div><div className="app-post-products">{item.appResearch?.appNames.map(name=><Badge key={name} variant="outline">{name}</Badge>)}</div><p>{item.summary||'帖子内容等待完整观察。'}</p></div></div><div className="app-post-dimensions">{item.appResearch?.dimensions.map(dimension=><Badge key={dimension} variant="outline">{dimension}</Badge>)}</div><div className="app-post-footer"><span>{item.author}</span><span><Heart size={12}/>{number(item.metrics.likes.value)}</span><button onClick={()=>void onOpen(runId,item.id,'comments')}><MessageCircle size={12}/>{item.comments.length} 条已采评论 · {item.commentSampling.readStatus==='all_visible'?'可见评论已读完':item.commentSampling.readStatus==='blocked'?'读取受阻':'待续读'}</button></div></CardContent></Card>)}</div>{!filtered.length&&<Empty title={samples.length?'暂无匹配的 App 帖子':'还没有 App 调研数据'} icon={<Smartphone size={30}/>}>{samples.length?'调整分组、帖子类型或搜索条件。':'创建调研请求后，由 Codex 使用 ego 采集小红书帖子、截图及评论，完成后刷新查看。'}</Empty>}<div className="limitations"><ShieldCheck size={14}/><div><p>优先观察功能诉求、会员价格、数据记录与导出、手表同步、AI效果和留存障碍。</p><p>点赞和推广评论不代表产品用户量或付费意愿；独立开发者身份需要原帖中的明确依据。</p></div></div></div>;
}

function TimelineView({runs,onSelect}: {runs:Bootstrap['runs'];onSelect:(id:string,target:'overview'|'library')=>void}) {
  const [order,setOrder]=useState<'desc'|'asc'>('desc');
  const ordered=[...runs].sort((a,b)=>(Date.parse(b.startedAt)-Date.parse(a.startedAt))*(order==='desc'?1:-1));
  const days=new Map<string,Bootstrap['runs']>();
  for(const run of ordered) {
    const day=new Date(run.startedAt).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});
    const group=days.get(day)??[];group.push(run);days.set(day,group);
  }
  const time=(value:string)=>new Date(value).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'});
  return <div className="page-content timeline-page"><div className="timeline-toolbar"><div><h2>采集时间轴 <span>{runs.length} 个批次</span></h2><p>以批次开始时间排列 · 北京时间</p></div><FilterSelect label="时间轴排序" value={order} onValueChange={value=>setOrder(value as 'desc'|'asc')} options={[{value:'desc',label:'最新在前'},{value:'asc',label:'最早在前'}]}/></div>{[...days].map(([day,records])=><section className="timeline-day" key={day}><div className="timeline-day-heading"><CalendarDays size={15}/><h3>{day}</h3><span>{records.length} 次采集</span></div><div className="timeline-events">{records.map(run=><article key={run.id} className={`timeline-event timeline-${run.status}`}><div className="timeline-event-time"><span className="timeline-dot"/><strong>{time(run.startedAt)}</strong><span>开始采集</span></div><div className="timeline-event-card"><div className="timeline-event-header"><div><Badge variant="outline">{run.track==='app_research'?'App 调研':run.mode==='historical_import'?'历史样本导入':'每日内容采集'}</Badge><span>{run.date} 采集批次</span></div><Badge variant={run.status==='complete'?'secondary':'outline'}>{statuses[run.status]}</Badge></div><h3>{run.report.summary || (run.status==='blocked'?'采集遇到阻塞，等待处理':run.status==='collecting'?'正在收集内容与评论':'本批次研究摘要待整理')}</h3><div className="timeline-counts"><span><Platform platform="douyin"/><strong>{run.selectedIds.filter(id=>id.startsWith('douyin:')).length}</strong>条入选</span><span><Platform platform="xiaohongshu"/><strong>{run.selectedIds.filter(id=>id.startsWith('xiaohongshu:')).length}</strong>条入选</span><span><Search size={12}/>{new Set(run.coverage.map(c=>c.keyword)).size} 个已记录搜索词</span></div>{run.report.findings.length>0&&<ul className="timeline-findings">{run.report.findings.slice(0,2).map((finding,index)=><li key={index}>{finding}</li>)}</ul>}{run.report.opportunities[0]&&<div className="timeline-opportunity"><Lightbulb size={14}/><p><strong>关注方向</strong>{run.report.opportunities[0]}</p></div>}{run.status!=='complete'&&run.report.limitations[0]&&<p className="timeline-gap"><ShieldCheck size={12}/>{run.report.limitations[0]}</p>}<div className="timeline-event-footer"><span>{run.finishedAt?`结束于 ${new Date(run.finishedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}`:'尚未结束'}<small>{run.id}</small></span><button onClick={()=>onSelect(run.id,'overview')}>查看汇总<ArrowRight size={12}/></button><Button variant="outline" size="sm" onClick={()=>onSelect(run.id,'library')}>查看内容</Button></div></div></article>)}</div></section>)}{!runs.length&&<Empty title="还没有时间轴记录" icon={<CalendarDays size={30}/>}>保存第一批采集数据后，会自动按时间显示。</Empty>}</div>;
}

function RunsView({data,onSelect}: {data:Bootstrap|null;onSelect:(id:string)=>void}) {
  const run=data?.run;
  return <div className="page-content"><div className="section-title"><h2>采集批次</h2>{run&&<Button variant="outline" onClick={()=>download(`${run.id}.json`,run)}><Download/>导出当前批次</Button>}</div><div className="run-table"><div className="run-table-head"><span>批次 / 日期</span><span>状态</span><span>抖音入选</span><span>小红书入选</span><span>操作</span></div>{data?.runs.map(r=><div key={r.id} className="run-table-row"><span data-label="批次 / 日期"><strong>{r.date}</strong><small>{r.id}</small></span><Badge variant={r.status==='complete'?'secondary':'outline'}>{statuses[r.status]}</Badge><span data-label="抖音入选">{r.track==='app_research'?'不采集':`${r.selectedIds.filter(id=>id.startsWith('douyin:')).length}${r.mode==='historical_import'?'':' / 50'}`}</span><span data-label="小红书入选">{r.selectedIds.filter(id=>id.startsWith('xiaohongshu:')).length}{r.mode!=='historical_import'&&` / ${r.track==='app_research'?r.config.appResearch.postsPerGroup*2:50}`}</span><button onClick={()=>onSelect(r.id)}>查看<ArrowRight size={13}/></button></div>)}{!data?.runs.length&&<Empty title="还没有采集记录">新建采集后，在 Codex 中执行对应 Skill。</Empty>}</div>{run&&<><div className="section-title"><h2>当前批次的搜索覆盖</h2><Badge variant="outline">{run.mode==='historical_import'?'历史导入':'每日采集'}</Badge></div><div className="coverage-grid">{run.coverage.map((c,index)=><Card key={index}><CardContent><div><Platform platform={c.platform}/><strong>{c.keyword}</strong><span>{c.scanned} 条候选</span></div><p>{c.sort} · {c.timeWindow}</p><p>{c.stopReason}</p>{c.sourceUrl&&<a href={c.sourceUrl} target="_blank" rel="noreferrer">查看搜索来源<ExternalLink size={12}/></a>}</CardContent></Card>)}</div><div className="limitations"><ShieldCheck size={16}/><div>{run.report.limitations.map((l,i)=><p key={i}>{l}</p>)}</div></div></>}<div className="section-title"><h2>等待 Codex 执行的请求</h2></div><div className="requests-list">{data?.requests.map(r=><div key={r.id}><span>{r.date}<small>{new Date(r.createdAt).toLocaleString('zh-CN')}</small></span><Badge variant="outline">{({pending:'待执行',running:'执行中',done:'已处理',blocked:'需处理'} as const)[r.status]}</Badge>{r.runId&&<button onClick={()=>onSelect(r.runId!)}>查看批次</button>}<span className="subtle">请求文件已保存本地</span></div>)}{!data?.requests.length&&<p className="subtle">暂无待执行请求。WebUI 不会自行启动浏览器。</p>}</div></div>;
}
function SettingsView({config,onSave}: {config:Config;onSave:(c:Config)=>Promise<void>}) {
  const [draft,setDraft]=useState(config); const [keywordText,setKeywordText]=useState(config.keywords.join('\n')); const [saving,setSaving]=useState(false); const [error,setError]=useState('');
  async function save(){setSaving(true);setError('');try{await onSave({...draft,keywords:keywordText.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean),appResearch:{...draft.appResearch,mainstreamApps:draft.appResearch.mainstreamApps.map(s=>s.trim()).filter(Boolean),keywords:draft.appResearch.keywords.map(s=>s.trim()).filter(Boolean)}});}catch(e){setError((e as Error).message);}finally{setSaving(false);}}
  return <div className="page-content settings-page"><Card><CardHeader><CardTitle>采集范围</CardTitle><Badge variant="secondary">抖音 + 小红书</Badge></CardHeader><CardContent><div className="settings-fields"><label>发布时间范围<FilterSelect label="发布时间范围" value={String(draft.windowDays)} onValueChange={value=>setDraft({...draft,windowDays:Number(value)})} options={[1,7,30,90].map(days=>({value:String(days),label:`近 ${days} 天`}))}/><small>每日执行，默认观察近 7 天发布的内容。</small></label><label>各平台入选数量<Input value="50 条" disabled/><small>跨关键词去重后，按可见累计点赞排序。</small></label><label>每关键词候选数<Input type="number" min={20} max={300} value={draft.candidatePerKeyword} onChange={e=>setDraft({...draft,candidatePerKeyword:Number(e.target.value)})}/><small>候选池越大，采集所需时间越长。</small></label><label>每条热评目标<Input type="number" min={10} max={500} value={draft.commentsPerItem} onChange={e=>setDraft({...draft,commentsPerItem:Number(e.target.value)})}/></label><label>每条最新评论目标<Input type="number" min={0} max={100} value={draft.recentCommentsPerItem} onChange={e=>setDraft({...draft,recentCommentsPerItem:Number(e.target.value)})}/></label><label>每条关键帧目标<Input type="number" min={3} max={12} value={draft.frameCount} onChange={e=>setDraft({...draft,frameCount:Number(e.target.value)})}/></label></div><label className="keyword-setting">搜索关键词<Textarea rows={7} value={keywordText} onChange={e=>setKeywordText(e.target.value)} placeholder="每行一个关键词"/><small>健身、运动健康、体态分析、减脂减肥、增肌等方向；每行一个关键词。</small></label><label className="checkbox-setting"><Checkbox checked={draft.includePromotion} onCheckedChange={checked=>setDraft({...draft,includePromotion:checked})}/>保留商业内容参与候选排序，并单独标记</label>{error&&<p className="form-error">{error}</p>}<Button disabled={saving} onClick={()=>void save()}>{saving?<LoaderCircle className="spin"/>:<Check/>}保存采集设置</Button></CardContent></Card><Card><CardHeader><CardTitle>执行方式与数据</CardTitle></CardHeader><CardContent><div className="execution-flow"><span>Codex + Skill</span><ArrowRight size={14}/><span>ego 浏览器</span><ArrowRight size={14}/><span>本地 JSON / 截帧</span><ArrowRight size={14}/><span>研究界面</span></div><p>每天的调度由 Codex 自动化执行。WebUI 只创建待执行请求、读取本地数据，不在页面内运行 Agent。</p><p>数据目录：data/runs、data/assets、data/requests。个人笔记和采集数据均被 Git 忽略。</p><p>登录或验证由本人处理，采集会保存进度；缺失指标显示为“—”。</p></CardContent></Card></div>;
}
function CollectDialog({open,onOpenChange,config,onCreated,notify,track}: {track:'daily'|'app_research';open:boolean;onOpenChange:(o:boolean)=>void;config?:Config;onCreated:(r:CollectionRequest)=>void;notify:(s:string)=>void}) {
  const [date,setDate]=useState(dateInShanghai()); const [request,setRequest]=useState<CollectionRequest|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
  useEffect(()=>{if(open){setRequest(null);setError('');}},[open]);
  async function create(){setBusy(true);setError('');try{const r=await api<CollectionRequest>('requests',{method:'POST',body:JSON.stringify({date,track})});setRequest(r);onCreated(r);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="collect-dialog"><DialogHeader><DialogTitle>{track==='app_research'?'新建 App 调研':'开始一次内容研究'}</DialogTitle><DialogDescription>创建本地请求，再将指令交给 Codex 执行。</DialogDescription></DialogHeader><div className="collect-steps"><span className="active">1 配置范围</span><ArrowRight size={13}/><span className={request?'active':''}>2 交给 Codex</span><ArrowRight size={13}/><span>3 刷新查看</span></div><label>采集日期<Input type="date" value={date} onChange={e=>setDate(e.target.value)} disabled={!!request}/></label><div className="collect-scope"><span>{track==='app_research'?`小红书 · 主流产品与独立产品各 ${config?.appResearch.postsPerGroup??10} 条`:'抖音 50 + 小红书 50'}</span><span>近 {track==='app_research'?(config?.appResearch.windowDays??30):(config?.windowDays??7)} 天 · 可见评论与内容</span><p>{track==='app_research'?[...(config?.appResearch.mainstreamApps??[]),...(config?.appResearch.keywords??[])].join(' / '):config?.keywords.join(' / ')}</p></div>{request?<><div className="prompt-box"><p>{request.prompt}</p></div><Button onClick={async()=>{try{await navigator.clipboard.writeText(request.prompt);notify('已复制，请粘贴到 Codex 执行');}catch{setError('剪贴板不可用，请手动选中指令复制。');}}}><Copy/>复制 Codex 指令</Button><p className="subtle">请求已保存 data/requests/{request.id}.json。创建请求不代表采集已启动。</p></>:<Button onClick={()=>void create()} disabled={busy||!date}>{busy?<LoaderCircle className="spin"/>:<Plus/>}创建采集请求</Button>}{error&&<p className="form-error">{error}</p>}</DialogContent></Dialog>;
}
export default App;
